// SAADFX Mobile - app builder helper. Designed by Muhammad Saad.
// GitHub runs this file to turn index.html into the Android (APK) and iPhone (IPA) app.
// node setup.js pre | android | ios
const fs = require('fs'), path = require('path');
const D = {"androidIcons": {"mdpi": "", "hdpi": "", "xhdpi": "", "xxhdpi": "", "xxxhdpi": ""}, "androidSplash": "iVBORw0KGgoAAAANSUhEUgAAABAAAAAQCAIAAACQkWg2AAAAGUlEQVR42mPk4uRmIAUwMZAIRjWMahg6GgCPswA+yfmoXQAAAABJRU5ErkJggg==", "iosIcon": "", "iosSplash": "", "keystore": ""};
const step = process.argv[2];
const w = (p, s) => { fs.mkdirSync(path.dirname(p), { recursive: true }); fs.writeFileSync(p, s); console.log('wrote', p); };
const b = s => Buffer.from(s, 'base64');
function walk(dir, out = []) { for (const f of fs.readdirSync(dir, { withFileTypes: true })) { const p = path.join(dir, f.name); if (f.isDirectory()) walk(p, out); else out.push(p); } return out; }

if (step === 'pre') {
  w('package.json', JSON.stringify({
    name: 'saadfx-mobile', version: '1.0.0', private: true, description: 'SAADFX Mobile - Designed by Muhammad Saad',
    dependencies: {
      '@capacitor/core': '^6.2.0', '@capacitor/cli': '^6.2.0', '@capacitor/android': '^6.2.0', '@capacitor/ios': '^6.2.0',
      '@capacitor/filesystem': '^6.0.0', '@capacitor/share': '^6.0.0'
    }
  }, null, 2));
  w('capacitor.config.json', JSON.stringify({
    appId: 'com.muhammadsaad.saadfxmobile', appName: 'SAADFX Mobile', webDir: 'www',
    backgroundColor: '#0a090b',
    android: { allowMixedContent: false, captureInput: false, webContentsDebuggingEnabled: false },
    ios: { contentInset: 'never', scrollEnabled: true, limitsNavigationsToAppBoundDomains: false }
  }, null, 2));
  if (!fs.existsSync('index.html')) { console.error('index.html is missing: upload SAADFX Mobile index.html to the repository'); process.exit(1); }
  w('www/index.html', fs.readFileSync('index.html'));
}

if (step === 'android') {
  const res = 'android/app/src/main/res';
  for (const [d, png] of Object.entries(D.androidIcons)) {
    w(`${res}/mipmap-${d}/ic_launcher.png`, b(png));
    w(`${res}/mipmap-${d}/ic_launcher_round.png`, b(png));
  }
  fs.rmSync(`${res}/mipmap-anydpi-v26`, { recursive: true, force: true });   // use the SAADFX icon, not the adaptive Capacitor one
  for (const f of walk(res)) if (path.basename(f) === 'splash.png') w(f, b(D.androidSplash));
  // manifest: older Android needs storage permission for Documents/SAADFX
  const mf = 'android/app/src/main/AndroidManifest.xml';
  let m = fs.readFileSync(mf, 'utf8');
  if (!m.includes('WRITE_EXTERNAL_STORAGE')) m = m.replace('</manifest>', '    <uses-permission android:name="android.permission.WRITE_EXTERNAL_STORAGE" android:maxSdkVersion="29" />\n    <uses-permission android:name="android.permission.READ_EXTERNAL_STORAGE" android:maxSdkVersion="32" />\n</manifest>');
  if (!m.includes('requestLegacyExternalStorage')) m = m.replace('<application', '<application\n        android:requestLegacyExternalStorage="true"');
  w(mf, m);
  // the same signing key every time, so new versions install over the old one and keep your work
  w('android/app/saadfx.keystore', b(D.keystore));
  const g = 'android/app/build.gradle';
  let gr = fs.readFileSync(g, 'utf8');
  if (!gr.includes('signingConfigs.saadfx')) {
    gr += `
android {
    signingConfigs {
        saadfx {
            storeFile file('saadfx.keystore')
            storePassword 'saadfx2026'
            keyAlias 'saadfx'
            keyPassword 'saadfx2026'
        }
    }
    buildTypes {
        debug { signingConfig signingConfigs.saadfx }
        release { signingConfig signingConfigs.saadfx; minifyEnabled false }
    }
}
`;
    w(g, gr);
  }
}

if (step === 'ios') {
  const assets = 'ios/App/App/Assets.xcassets';
  const icDir = `${assets}/AppIcon.appiconset`;
  for (const f of fs.existsSync(icDir) ? fs.readdirSync(icDir) : []) if (f.endsWith('.png')) fs.rmSync(path.join(icDir, f));
  w(`${icDir}/AppIcon-512@2x.png`, b(D.iosIcon));
  w(`${icDir}/Contents.json`, JSON.stringify({ images: [{ filename: 'AppIcon-512@2x.png', idiom: 'universal', platform: 'ios', size: '1024x1024' }], info: { author: 'xcode', version: 1 } }, null, 2));
  const spDir = `${assets}/Splash.imageset`;
  if (fs.existsSync(spDir)) for (const f of fs.readdirSync(spDir)) if (f.endsWith('.png')) w(path.join(spDir, f), b(D.iosSplash));
  const pl = 'ios/App/App/Info.plist';
  let p = fs.readFileSync(pl, 'utf8');
  const add = (k, v) => { if (!p.includes(`<key>${k}</key>`)) { const i = p.lastIndexOf('</dict>'); p = p.slice(0, i) + `\t<key>${k}</key>\n\t${v}\n` + p.slice(i); } };
  add('NSPhotoLibraryAddUsageDescription', '<string>SAADFX Mobile saves your lyric videos to Photos.</string>');
  add('NSPhotoLibraryUsageDescription', '<string>SAADFX Mobile can use your photos.</string>');
  add('UIFileSharingEnabled', '<true/>');
  add('LSSupportsOpeningDocumentsInPlace', '<true/>');
  add('UIStatusBarStyle', '<string>UIStatusBarStyleLightContent</string>');
  w(pl, p);
}
